evaluator.text:
# ASI-Bench manifest. 语言：中文说明，键名英文。
# 事实来源：REPO = https://github.com/apexin-ai/ASI-Bench @ d54f25016e9eaa4db366edcacce945bd6552b97f（2026-10-29）；
#   HF = https://huggingface.co/datasets/Apexintelligence-AI/ASI-Bench-seed31415 @ 0fa14219cafdbab634d8b3cfbce238a8735a214f
#   （2026-10-07，不 gated，metadata.json 的 source_commit 是 apexin-ai/Agent-AI4Sci-Bench 6192234）；
#   LB = https://asibench.apexin.ai/data/leaderboard_preview.json（2026-09-06 快照，2026-10-30 读取）。
id: asibench
name: ASI-Bench（seed31415，B3/B4）
manifest_date: 2026-10-30

status_summary: >-
  60 个项目级计算科学任务、11 个领域；两个固定版本的资产（仓库、HF 数据集）已登记。本项目只取 B3（只给目标和数据）与 B4（B3 加
  一段无关但事实正确的背景）两个指导级别，B1、B2 给出方法，不是研究，不纳入。条目是 `<任务>__<级别>`。4 道需要联网的题留在
  `items` 里但移出批次（`plan.excluded`）。评分是官方的确定性 scorer，13 道题的 scorer 用 LLM/VLM 判官（官方是 gpt-5.5），
  这里换成 codex-api 提供的 GPT，分数照官方代码记录，实际服务的模型写在分数里。

source:
  paper:
    title: "ASI-Bench: At the Dawn of Artificial Superintelligence"
    authors: ["Junwei Zhou", "Zhen Sun", "Binyu Li", "Jiangyu Zhou", "Yuexi Pan", "Hengyu Wang", "Honghe Ren", "Xiaohan Jia", "Xueyang Zhou", "Xiaoyu Cao", "Yongchao Chen"]
    arxiv: https://arxiv.org/abs/2608.17271
    venue: arXiv 2608.17271（v1 2026-08-18）
    source: REPO README.md（Paper 段与作者表）
  repo:
    url: https://github.com/apexin-ai/ASI-Bench
    pinned_commit: d54f25016e9eaa4db366edcacce945bd6552b97f
    pinned_commit_date: "2026-10-29T10:55:07-07:00"
    source: git log -1 --format=%H%n%cI（2026-10-30 在固定提交的检出里读取）
  dataset:
    hf: https://huggingface.co/datasets/Apexintelligence-AI/ASI-Bench-seed31415
    revision: 0fa14219cafdbab634d8b3cfbce238a8735a214f
    content: "60 个实例（prompt_b1–b4.md、data/、reference/、instance_meta.json、framework_task_info.json），共 1531 个文件、约 119 MB；reference/ 是参考输出和 scorer 用的比较文件，只在评测侧"
    seed42: "https://huggingface.co/datasets/Apexintelligence-AI/ASI-Bench-seed42：参考答案私有，只能提交官方网站打分，本项目不用"
    source: HF API tree（recursive）与 metadata.json（task_count 60，seed_overrides 两题用 seed 2）
  task_stats:
    tasks: 60
    note: "metadata.json 的 task_status 写 59 个 final 加 1 个应要求加入的测试题；task_meta.yaml 里 60 题的 status 都是 final，哪一题是测试题没有标出"
    domains: {math: 12, computer_science: 9, physics: 8, robotics: 7, biology: 6, chemistry: 6, earth_science: 4, astronomy: 3, electrical_engineering: 2, materials: 2, biostat: 1}
    source: task_meta.yaml 的 domain 逐题统计（与 HF 文件树一致）

license:
  code:
    spdx: Apache-2.0
    redistribution: 允许
    source: REPO LICENSE（Apache-2.0）；GitHub API license.spdx_id
  data:
    spdx: Apache-2.0
    source: HF 数据集卡 front matter 与 LICENSE
    caveat: "实例数据由任务的生成器按种子合成，数据集卡只给整体的 Apache-2.0；没有逐题的第三方数据说明"

subset:
  rule: >
    条目只取 B3 和 B4（Issue #94，维护者 2026-10-30）；4 道 task_meta.yaml 写 requires_network: true 的题
    （chemistry.metadynamics_for_dipeptide_in_vacuum、chemistry.sapt_water_dimer、math.ill_posed_inverse_problem、
    math.manifold_pde_meshfree）不进批次，因为本项目的被测系统在联网屏蔽下运行。60 题都是 requires_gpu: false。
  tasks_selected: 40
  level_decision: >
    只取 B3（维护者 2026-10-30 确认）：B4 只是在 B3 上加一段无关背景，公开榜单上 21 行里 B3 − B4 的均值只有 −0.15 分，B4 题面约是 B3 的
    1.7 倍长。
  formal_batch:
    rule: >
      正式批次的准入标准（Issue #94 和 #86，维护者 2026-10-30 定为 60 分钟）：去掉 4 道联网题后的 56 题里，官方 task_meta.yaml 的
      estimated_time_minutes 取区间中点（单个数就是它自己）不到 60 分钟的 16 题不进，其余 40 题的 B3 进批次 asibench-subset。依据是官方作者
      对每道题的耗时估计，是任务自己的属性，不是任何被测系统的得分；它是估计而不是实测，榜单没有逐题耗时。批次文件由下面 tasks 逐题的
      estimated_time_minutes 按这条规则得出，测试会重算核对。
    threshold_min: 60
    basis: midpoint
    excluded_shortest_first: [robotics.robust_pose_graph_false_loops, astronomy.white_dwarf_sparse_inference, math.symplectic_integrators, math.sigma_linear_diophantine, physics.vpfm_leapfrog, biostat.perturbation_convergence_testing, math.levin_context_grid_search, math.mpsc_safety_filter, robotics.lidar_imu_time_offset_yaw_calibration, biology.calcium_ip3_dyk_oscillations, biology.gene_network_timeseries, earth_science.2_e_soil_carbon_nitrogen_cycling, materials.ising_domain_growth, physics.ks_2d_anisotropic, robotics.multiregime_icp_degeneracy, biology.contextual_dna_regime_mapping]
    kept: 40
    excluded_networked: [chemistry.metadynamics_for_dipeptide_in_vacuum, chemistry.sapt_water_dimer, math.ill_posed_inverse_problem, math.manifold_pde_meshfree]
official_protocol:
  agent_workspace: "data/（实例输入）、prompt.md（该级别的提示）、task_info.json（匿名任务 id、级别、输出文件名与类型、超时）"
  prompt: "prompt_<级别>.md 原文交给 agent；各 CLI agent 的适配器只在后面加一段使用工作区 Python 的运行说明"
  time_limit: "10800 秒（`asibench run --timeout` 默认值，README Run configuration）；论文报告平均每题 38–50 分钟"
  resources: "OS 沙箱默认 4 CPU、8 GB 内存（runner/os_sandbox.py DEFAULT_CPU_LIMIT、DEFAULT_MEMORY_LIMIT）"
  network: "沙箱只在任务 requires_network 为真时联网；官网写明已发表的评测在没有外部工具访问下进行（LB 页 Scoring Methodology）"
  scoring: "`asibench score` / `benchflow-score`：每题 task_eval.yaml 的 gates 与 scoring（确定性 scorer 加权，部分题用 LLM/VLM 判官），报告本地、非官方分数"
  leaderboard:
    url: https://asibench.apexin.ai/leaderboard
    note: >-
      榜单给每个 agent × 模型的 B1–B4 汇总，没有逐题分数。Issue 里的 55.84（Codex + GPT-5.6 Sol）和 50.29（Claude Code +
      Claude Opus 5）是 B1–B4 四个级别的均值；只看 B3，它们是 51.60 和 40.70（B4 是 50.41 和 42.39；2026-10-31 核对：先前写的 40.74 是 Codex + GPT-5.6 Sol（xhigh）的 B4，不是
      Claude Code + Claude Opus 5 的 B3）。官方 README 说榜单只收 seed42（参考答案私有）的提交，本项目用 seed31415 的公开参考答案；论文和榜单没有写已发表分数用的是哪个 seed。

published_scores:
  read_date: 2026-10-31
  source: "论文 arXiv 2608.17271 Table 2（只有 v1，2026-08-18）；官方榜单数据 https://asibench.apexin.ai/data/leaderboard_preview.json（website_snapshot_updated 2026-09-06，21 行，publication_status review-required，sha256 6ea24c82…）"
  scope: "60 个项目级任务、11 个领域，B1–B4 四个指导级别；分数是每题得分对 60 题的宏平均（0–100），再对 3 次独立运行平均（Claude Opus 5 与榜单上的 Qwen3.8-Max 只有 1 次）。评测在无外部工具访问下进行（论文 Table 2、榜单 Scoring Methodology）"
  subset_recompute: "无法重算：论文和榜单都没有逐题或逐领域分数（榜单写明不从逐题产物重算），我们 40 题 B3 批次 0/40 找到；只有全集 60 题的 B3 汇总数"
  judge: "论文和榜单没有写 judge 模型；榜单写明 exact task-set version remains explicitly unverified，也没有写已发表分数用的 seed"
  cc_sonnet: "没有 Sonnet 的任何配置；最近的 Claude Code 条目是 Claude Code + Claude Opus 5（Max，1 次运行）和 Claude Opus 4.8（Max，3 次运行）"
  b3_full_60:
    - {system: "Codex", model: "GPT-5.6 Sol (ultra)", b3: 51.60, b4: 50.41, overall: 55.84, repeats: 3, cost_usd_per_run: 1550}
    - {system: "Claude Code", model: "Claude Opus 5 (effort Max)", b3: 40.70, b4: 42.39, overall: 50.29, repeats: 1, cost_usd_per_run: 2728}
